const rows = $input.all().map(i => i.json);
const results = [];

for (const r of rows) {
  const priceAt = parseFloat(r.price_at_signal);
  const priceNow = parseFloat(r.current_price);
  if (!priceAt || !priceNow) continue;

  const pctChange = ((priceNow - priceAt) / priceAt) * 100;

  let outcome = 'NEUTRAL';
  const THRESHOLD = 0.3; // % thay doi toi thieu de tinh la co y nghia
  if (r.signal === 'BUY') {
    if (pctChange > THRESHOLD) outcome = 'CORRECT';
    else if (pctChange < -THRESHOLD) outcome = 'INCORRECT';
  } else if (r.signal === 'SELL') {
    if (pctChange < -THRESHOLD) outcome = 'CORRECT';
    else if (pctChange > THRESHOLD) outcome = 'INCORRECT';
  }

  results.push({
    signal_id: r.id,
    symbol: r.symbol,
    signal: r.signal,
    confidence: r.confidence,
    price_at_signal: priceAt,
    price_evaluated: priceNow,
    pct_change: Math.round(pctChange * 100) / 100,
    outcome
  });
}

return results.map(r => ({ json: r }));
